import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Android.html","title":"Android","lang":"en-US","frontmatter":{},"git":{"createdTime":1638064324000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":15}]},"readingTime":{"minutes":0.84,"words":252},"filePathRelative":"Android.md"}`),a={name:`Android.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="android" tabindex="-1"><a class="header-anchor" href="#android"><span>Android</span></a></h1><h2 id="このwiki内の関連リンク" tabindex="-1"><a class="header-anchor" href="#このwiki内の関連リンク"><span>このWiki内の関連リンク</span></a></h2><ul><li><a href="./JetpackCompose.html">JetpackCompose</a></li><li><a href="./StorageAccessFramework.html">StorageAccessFramework</a></li><li><a href="./RecyclerView.html">RecyclerView</a></li><li><a href="./Kotlin.html">Kotlin</a></li><li><a href="./LenovoTabP12.html">LenovoTabP12</a></li><li><a href="./スマホ.html">スマホ</a></li><li><a href="./KindleFire.html">KindleFire</a></li><li><a href="./FDroid.html">FDroid</a></li><li><a href="./PDF.html">PDF</a></li></ul><h2 id="開発リンク" tabindex="-1"><a class="header-anchor" href="#開発リンク"><span>開発リンク</span></a></h2><ul><li><a href="https://developer.android.com/studio/command-line/adb" target="_blank" rel="noopener noreferrer">Android Debug Bridge (adb) \xA0:\xA0 Android Developers</a> WiFiデバッグの説明。</li><li><a href="https://cs.android.com" target="_blank" rel="noopener noreferrer">Android code search</a></li><li><a href="https://developer.android.com/jetpack/androidx/versions/stable-channel" target="_blank" rel="noopener noreferrer">Stable Releases \xA0-\xA0 Jetpack \xA0|\xA0 Android Developers</a></li><li><a href="./あおぞらAndroid教室.html">あおぞらAndroid教室</a></li><li><a href="https://developer.android.com/guide/topics/connectivity/nfc/nfc?hl=ja" target="_blank" rel="noopener noreferrer">NFC の基本 \xA0-\xA0 Connectivity \xA0|\xA0 Android Developers</a></li><li><a href="https://developer.android.com/courses/android-basics-kotlin/course" target="_blank" rel="noopener noreferrer">Android Basics in Kotlin course \xA0-\xA0 Android Developers</a> code labsとか</li><li><a href="https://developer.android.com/develop/ui/views/graphics/agsl" target="_blank" rel="noopener noreferrer">Android Graphics Shading Language (AGSL) \xA0-\xA0 Views \xA0-\xA0 Android Developers</a> AGSLなんて出来てたのか。びっくりするほどドキュメントがなくGLSLとの違いが全然分からんが。</li><li><a href="https://fonts.google.com/icons" target="_blank" rel="noopener noreferrer">Material Symbols &amp; Icons - Google Fonts</a> マテリアルデザインのアイコン</li></ul><h2 id="launcherアイコンの作り方" tabindex="-1"><a class="header-anchor" href="#launcherアイコンの作り方"><span>launcherアイコンの作り方</span></a></h2><p>最近はAndroidの Asset Studioを使うのが良い。 AndroidStudioから、</p><p><code>メニュー＞View＞Tool Window＞Resource Manager</code></p><p>を選ぶ。 上の所の+を選び、Launcher iconを選びAsset typeをImageにして、 512x512とかの大きめのpngを用意して指定し、TrimをYesにするとだいたい良きに計らってくれる。</p><p>前は以下だった。</p><p><code>メニュー＞File＞New＞Image Asset</code></p><h2 id="no-user-data-collectedな時のprivacy-policyの書き方" tabindex="-1"><a class="header-anchor" href="#no-user-data-collectedな時のprivacy-policyの書き方"><span>no user data collectedな時のPrivacy Policyの書き方</span></a></h2><p>以下にあるように、データを集めてない、というPrivacy Policyが必要らしい。</p><p><a href="https://support.google.com/googleplay/android-developer/answer/10787469?hl=en" target="_blank" rel="noopener noreferrer">Provide information for Google Play&#39;s Data safety section - Play Console Help</a></p><h2 id="adbのソースコードの場所" tabindex="-1"><a class="header-anchor" href="#adbのソースコードの場所"><span>adbのソースコードの場所</span></a></h2><p>そのうちMacとの間の移動のアプリとか書きたいなぁ、と思い、adbのソースコードの場所をメモしておく。</p><p><a href="https://android.googlesource.com/platform/system/adb" target="_blank" rel="noopener noreferrer">platform/system/adb - Git at Google</a></p><p>adb shellとかのGUIラッパくらいでいいかな、とは思っている。</p><h2 id="sdk-33へのアップデート作業" tabindex="-1"><a class="header-anchor" href="#sdk-33へのアップデート作業"><span>SDK 33へのアップデート作業</span></a></h2><p>gradle/wrapper/gradle-wrapper.propertiesを <code>distributionUrl=https\\://services.gradle.org/distributions/gradle-8.3-bin.zip</code>にする。</p><p>ルートのbuild.gradleで<code> classpath &#39;com.android.tools.build:gradle:8.1.1&#39;</code>とする。</p><p>アプリの方のbuild.gradleで以下みたいなnamespaceを作る（my.package.idはAndroidManifests.xmlのpackageに書いていたもの、AndroidManifestsの方は削除）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">android {</span>
<span class="line">...</span>
<span class="line">    namespace &#39;my.package.id&#39;</span>
<span class="line">    kotlinOptions {</span>
<span class="line">        jvmTarget = &#39;1.8&#39;</span>
<span class="line">    }</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>compileSdkVersionをcompileSdkに。</p><p>buildlToolsVersionは消す。</p><p>Settings＞Build, Execution, Deployment＞Gradle JDK を jbr 1.7に。</p><p>Playのページは一番左下のPolicy and programのApp contentに必要な事がまとまっている。</p>`,27)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};